
Object.assign(window.ISLAMA_EMBED,{
"v8-map.webp":"data:image/webp;base64,",
"v8-background.webp":"data:image/webp;base64,",
"v8-nomads.webp":"data:image/webp;base64,",
"v8-coast.webp":"data:image/webp;base64,",
"v8-goddess-uzza.webp":"data:image/webp;base64,",
"v8-goddess-lat.webp":"data:image/webp;base64,",
"v8-goddess-manat.webp":"data:image/webp;base64,"
});
/* Arabia ezagutzen V8 · HTML real e interactividad verificable; datos: PDF, pp. 3–5 */
(()=>{'use strict';
 const EMBED=window.ISLAMA_EMBED||{};
 const art=n=>EMBED['v8-'+n+'.webp']||'';
 const $=id=>document.getElementById('v8-'+id);
 const root=()=>document.getElementById('arabia-v8');
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const KEY='islama-v4-puntuazioak',TOTAL=15,MAXTIME=240;
 const stageNames=['','ARABIAR MAPA','TRIBUEN BIZIMODUA','ISLAMAREN AURREKO JAINKOSAK'];
 const locations=[
  {id:'arabia',label:'Arabiar penintsula',x:51,y:44,hint:'Itsaso Gorriaren eta Persiako golkoaren artean dago.',page:3},
  {id:'meka',label:'Meka',x:31.5,y:50.2,hint:'Arabiar penintsularen mendebaldean dago.',page:3},
  {id:'gorria',label:'Itsaso Gorria',x:25,y:43.5,hint:'Afrika eta Arabiar penintsula banatzen dituen itsasoa da.',page:3},
  {id:'pertsia',label:'Persiako golkoa',x:66,y:31,hint:'Arabiar penintsularen ipar-ekialdean dago.',page:3}
 ];
 const tribeFacts=[
  {id:'nomadak',text:'Nomadak ziren',answer:'barne',page:4},
  {id:'artzaintza',text:'Artzaintzan aritzen ziren',answer:'barne',page:4},
  {id:'fetixista',text:'Erlijio fetixista zuten',answer:'barne',page:4},
  {id:'sedentarioak',text:'Sedentarioak ziren',answer:'kosta',page:4},
  {id:'politeista',text:'Erlijio politeista zuten',answer:'kosta',page:4},
  {id:'nekazaritza',text:'Nekazaritzan aritzen ziren',answer:'kosta',page:4},
  {id:'merkataritza',text:'Merkataritzan aritzen ziren (karabanak)',answer:'kosta',page:4},
 ];
 const goddessQuestions=[
  {text:'Zein da goizeko izarraren jainkosa?',answer:'uzza',tip:'Goizeko izarrarekin lotzen da.',page:5},
  {text:'Zein da eguzkiaren jainkosa?',answer:'lat',tip:'Eguzkiarekin lotzen da.',page:5},
  {text:'Zein da denboraren jainkosa?',answer:'manat',tip:'Denborarekin lotzen da.',page:5}
 ];
 const goddessCards=[['uzza','Al-Uzza'],['lat','Al-Lat'],['manat','Manat']];
 let st=null,timer=null,muted=false;
 function sound(ok){if(muted||!window.AudioContext)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),gain=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(ok?720:230,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(ok?1060:150,ctx.currentTime+.17);gain.gain.setValueAtTime(.045,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(gain);gain.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.21);o.onended=()=>ctx.close()}catch{}}
 function readScores(){try{const data=JSON.parse(localStorage.getItem(KEY)||'{}');return data&&typeof data==='object'?data:{}}catch{return{}}}
 function leaderboard(){const s=readScores().arabia||{};return Object.values(s).filter(x=>x&&typeof x.score==='number').sort((a,b)=>b.score-a.score).slice(0,10)}
 function saveScore(){if(!st)return false;const scores=readScores();scores.arabia||={};const key=st.nickname.toLocaleLowerCase('eu');const score=scoreNow();if(!scores.arabia[key]||scores.arabia[key].score<score)scores.arabia[key]={name:st.nickname,score,timestamp:Date.now()};try{localStorage.setItem(KEY,JSON.stringify(scores));return true}catch{return false}}
 function scoreNow(){if(!st)return 0;const ratio=st.correct/TOTAL;return Math.min(1000,Math.round(840*ratio+160*ratio*st.time/MAXTIME))}
 function rankHtml(){const rows=leaderboard();return rows.length?rows.map((r,i)=>`<div class="v8-rank-row"><span class="v8-place">${i+1}.</span><span>${esc(r.name||'')}</span><strong>${Number(r.score).toLocaleString('eu-ES')}</strong></div>`).join(''):'<div class="v8-rank-empty">Oraindik ez dago puntuaziorik.<br/>Izan zaitez lehena!</div>'}
 function intro(){const r=root();if(!r)return;r.innerHTML=`<div class="v8-app" style="--v8-desert:url('${art('background')}')">
 <header class="v8-header"><button class="v8-home" data-action="home" aria-label="Menura itzuli">⌂</button><div class="v8-brand"><span class="v8-brand-small">ISLAMAREN<br/>ABENTURA</span><span class="v8-title">🏜️ ARABIA EZAGUTZEN</span></div><div class="v8-hud"><span class="v8-hud-pill v8-hearts" id="v8-lives">♥ ♥ ♥</span><span class="v8-hud-pill" id="v8-score">0 PUNTU</span><span class="v8-hud-pill" id="v8-time">04:00</span><button class="v8-sound" id="v8-sound" data-action="sound" aria-pressed="false" aria-label="Soinua isilarazi">♪</button></div></header>
 <div id="v8-intro" class="v8-intro"><div class="v8-intro-card"><div style="font-size:36px">✦ 🧭 ✦</div><h1>ARABIA EZAGUTZEN</h1><p>Hiru eremu, hamabost erronka: Arabiako mapa, tribuen bizimodua eta Islamaren aurreko jainkosak. PDFaren 3.–5. orrialdeetan oinarrituta.</p><div class="v8-intro-cards"><div>🗺️<br/><strong>1. MAPA</strong><br/>4 erronka</div><div>🐪<br/><strong>2. TRIBUAK</strong><br/>8 erronka</div><div>✦<br/><strong>3. JAINKOSAK</strong><br/>3 erronka</div></div><label for="v8-nickname" style="font:800 14px Arial,sans-serif">ZURE GOITIZENA</label><input id="v8-nickname" type="text" maxlength="18" placeholder="Adib.: Ikasle07" autocomplete="nickname"/><p id="v8-error" class="v8-error" role="alert"></p><button class="v8-primary" data-action="start">▶ JOLASTU</button><p style="font-size:12px;margin-top:20px">TOP 10 lokala · Demo honetan ez dago sailkapen partekaturik.</p></div></div>
 <div id="v8-play" class="v8-shell" hidden><div class="v8-level-track" id="v8-levels"></div><div class="v8-main"><aside class="v8-mission v8-parchment"><span class="v8-tag" id="v8-level-tag">1. MAILA</span><div class="v8-chapter-name" id="v8-chapter-name">Arabiako mapa</div><div class="v8-divider"></div><div class="v8-eyebrow" id="v8-challenge-number">1 / 15 ERRONKA</div><div class="v8-question" id="v8-question"></div><p class="v8-help" id="v8-help"></p><img class="v8-mission-art" id="v8-mission-art" alt=""/><div class="v8-feedback" id="v8-feedback" aria-live="polite">Hautatu erantzuna.</div><div class="v8-progress-label"><span>AURRERAPENA</span><span id="v8-progress-number">0 / 15</span></div><div class="v8-progress"><span id="v8-progress-fill"></span></div></aside><div class="v8-scene" id="v8-scene"></div><aside class="v8-parchment v8-ranking"><h2>🏆 TOP 10</h2><div class="v8-rank-list" id="v8-ranking"></div><div class="v8-local-label">SAILKAPEN LOKALA<br/>NABIGATZAILE HONETAN</div></aside></div><footer class="v8-footer"><span>✦ ISLAMAREN ABENTURA · 01. JOKOA</span><span id="v8-source">Iturria: PDF · 3. orrialdea</span><small id="v8-countdown">04:00</small></footer><div class="v8-transition" id="v8-transition" hidden></div></div>
 <div id="v8-complete" class="v8-complete" hidden></div></div>`;
 r.querySelector('#v8-nickname').value=lastNick();r.querySelector('#v8-nickname').focus();
 if(!r.dataset.v8Wired){
  r.addEventListener('click',onClick);r.addEventListener('dragstart',onDragStart);
  r.addEventListener('dragover',onDragOver);r.addEventListener('drop',onDrop);
  r.addEventListener('keydown',onKeyDown);r.addEventListener('dragend',clearDrag);
  r.dataset.v8Wired='1';
 }
 }
 function lastNick(){try{return localStorage.getItem('arabia-v8-nickname')||''}catch{return''}}
 function launch(){close();const host=document.createElement('div');host.id='arabia-v8';document.body.appendChild(host);document.body.style.overflow='hidden';intro();updateHud()}
 function close(){if(timer)clearInterval(timer);timer=null;root()?.remove();document.body.style.overflow='';st=null;}
 function start(){const nick=$('nickname')?.value.trim().normalize('NFC');if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(nick||'')){$('error').textContent='Idatzi 2–18 karaktereko goitizena (izen-abizenik gabe).';return}try{localStorage.setItem('arabia-v8-nickname',nick)}catch{}
 st={nickname:nick,stage:1,phase:'map',mapIndex:0,goddessIndex:0,tribePlaced:[],tribeOrder:shuffle(tribeFacts.map(x=>x.id)),selected:null,correct:0,errors:0,lives:3,time:MAXTIME,done:false,busy:false,unlocked:1,feedback:'',history:[]};$('intro').hidden=true;$('play').hidden=false;$('complete').hidden=true;render();timer=setInterval(()=>{if(!st||st.done)return;st.time=Math.max(0,st.time-1);updateHud();if(st.time<=0)finish()},1000);window.scrollTo({top:0,behavior:'instant'});}
 function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
 function updateHud(){const r=root();if(!r)return;$('score').textContent=scoreNow().toLocaleString('eu-ES')+' PUNTU';$('lives').textContent=st?'♥ '.repeat(st.lives)+'♡ '.repeat(3-st.lives):'♥ ♥ ♥';const t=st?st.time:MAXTIME;const time=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');$('time').textContent=time;if($('countdown'))$('countdown').textContent=time;if($('ranking'))$('ranking').innerHTML=rankHtml()}
 function completed(){if(!st)return 0;return st.correct}
 function render(){if(!st||st.done)return;const s=st;const name=stageNames[s.stage];$('levels').innerHTML=[1,2,3].map(n=>`<div class="v8-level ${n===s.stage?'active':''} ${n<s.stage?'done':''}" aria-current="${n===s.stage?'step':'false'}"><b>${n<s.stage?'✓':String(n).padStart(2,'0')}</b><span>${stageNames[n]}</span></div>`).join('');$('level-tag').textContent=s.stage+'. MAILA';$('chapter-name').textContent=name.charAt(0)+name.slice(1).toLocaleLowerCase('eu');$('challenge-number').textContent=(Math.min(TOTAL,completed()+1))+' / '+TOTAL+' ERRONKA';$('progress-number').textContent=completed()+' / '+TOTAL;$('progress-fill').style.width=(100*completed()/TOTAL)+'%';$('source').textContent='Iturria: PDF · '+(s.stage===1?'3.':s.stage===2?'4.':'5.')+' orrialdea';
 const q=s.stage===1?locations[s.mapIndex]:s.stage===3?goddessQuestions[s.goddessIndex]:null;
 if(s.stage===1){$('question').textContent='Non dago '+(q.id==='arabia'?'Arabiar penintsula':q.label)+'?';$('help').textContent='Begiratu mapa eta egin klik dagokion puntuan. Ez dira izenak erakusten erantzun arte.';$('mission-art').src=art('background');renderMap()}
 if(s.stage===2){if(s.phase==='common'){$('question').textContent='Zein dira Arabiako elementu komunak?';$('help').textContent='Aukeratu PDFaren 4. orrialdearekin bat datorren aukera.';$('mission-art').src=art('background');renderCommon()}else{$('question').textContent='Nola bizi ziren tribuak?';$('help').textContent='Arrastatu edo aukeratu ezaugarri bat eta kokatu barrualdeko edo kostaldeko tribuetan.';$('mission-art').src=art('nomads');renderTribes()}}
 if(s.stage===3){$('question').textContent=q.text;$('help').textContent='Hautatu izen egokia duen karta ilustratua.';$('mission-art').src=art('background');renderGoddesses()}
 $('feedback').className='v8-feedback';$('feedback').textContent=s.stage===2&&s.phase==='tribes'?'Aukeratu txartela eta sakatu dagokion eszena.':'Egin klik erantzun egokian.';updateHud();}
 function renderMap(){const buttons=locations.map((loc,i)=>`<button class="v8-pin" data-location="${loc.id}" style="left:${loc.x}%;top:${loc.y}%" aria-label="Mapako ${i+1}. puntu interaktiboa" title="Egin klik hemen"><span>✦</span></button>`).join('');$('scene').innerHTML=`<div class="v8-map-wrap"><div class="v8-map-top"><span>🧭 LURRALDEA EZAGUTZEN</span><span>4 KOKAPEN · MAPAN KLIK EGIN</span></div><div class="v8-map-frame"><img src="${art('map')}" alt="Arabiar penintsularen eta inguruko itsasoen mapa fisiko zehatza"/>${buttons}<div id="v8-map-reveal"></div></div><div class="v8-map-bottom"><span>✦ ARABIAREN KOKAPENA ✦</span><span>PDF · 3. orrialdea</span></div></div>`}
 function renderTribes(){const placed=st.tribePlaced;const chips=st.tribeOrder.filter(id=>!placed.includes(id)).map(id=>{const f=tribeFacts.find(x=>x.id===id);return `<button class="v8-token ${st.selected===id?'selected':''}" draggable="true" data-token="${id}" aria-pressed="${st.selected===id}">✥ ${esc(f.text)}</button>`}).join('');function tags(ans){return placed.map(id=>tribeFacts.find(x=>x.id===id)).filter(x=>x.answer===ans).map(f=>`<span>✓ ${esc(f.text)}</span>`).join('')}
 $('scene').innerHTML=`<div class="v8-tribes"><div class="v8-map-top"><span>🐪 BI BIZIMODU</span><span>${placed.length} / 7 KOKATUTA</span></div><div class="v8-tribe-scenes"><button class="v8-tribe-drop" data-tribe="barne" aria-label="Barrualdeko tribuak"><img src="${art('nomads')}" alt="Nomadak eta artzainak basamortuan"/><strong>BARRUALDEKOAK</strong><div class="v8-placed">${tags('barne')||'<span style="background:#fff5dc;border-style:dashed;color:#826542">Jarri ezaugarriak hemen</span>'}</div></button><button class="v8-tribe-drop" data-tribe="kosta" aria-label="Kostaldeko tribuak"><img src="${art('coast')}" alt="Nekazaritza eta merkatariak kostaldeko herrian"/><strong>KOSTALDEKOAK</strong><div class="v8-placed">${tags('kosta')||'<span style="background:#fff5dc;border-style:dashed;color:#826542">Jarri ezaugarriak hemen</span>'}</div></button></div><div class="v8-tribe-tray"><div class="v8-tray-head"><span>✥ AUKERATU ETA KOKATU TXARTELAK</span><span>${7-placed.length} GELDITZEN DIRA</span></div><div class="v8-token-grid">${chips}</div></div></div>`;}
 function renderCommon(){$('scene').innerHTML=`<div class="v8-common"><div class="v8-map-top"><span>✦ AZKEN ERRONKA: TRIBU GUZTIAK</span><span>PDF · 4. orrialdea</span></div><h3>Zeintzuk ziren Arabiako elementu komunak?</h3><div class="v8-common-answers"><button class="v8-answer" data-common="zuzena">Arabiera eta Harri Beltzari gurtza egitea</button><button class="v8-answer" data-common="oker1">Guztiak sedentarioak izatea</button><button class="v8-answer" data-common="oker2">Guztiak erlijio politeistakoak izatea</button></div></div>`}
 function renderGoddesses(){const cards=goddessCards.map(([id,label])=>`<button class="v8-goddess-card" data-goddess="${id}" aria-label="${label}"><img src="${art('goddess-'+id)}" alt="${esc(label)}; PDFko 5. orrialdeko iruditik egokitutako erretratua"/><strong>${esc(label)}</strong></button>`).join('');$('scene').innerHTML=`<div class="v8-goddess-stage"><div class="v8-map-top"><span>✦ ISLAMAREN AURREKO JAINKOSAK</span><span>${st.goddessIndex+1} / 3 ERRONKA</span></div><div class="v8-goddess-title">Al-Uzza · Al-Lat · Manat</div><div class="v8-goddess-grid">${shuffle(goddessCards).map(([id,label])=>`<button class="v8-goddess-card" data-goddess="${id}" aria-label="${label}"><img src="${art('goddess-'+id)}" alt="${esc(label)}; PDFko 5. orrialdeko iruditik egokitutako erretratua"/><strong>${esc(label)}</strong></button>`).join('')}</div></div>`}
 function feedback(ok,text){$('feedback').className='v8-feedback '+(ok?'good':'bad');$('feedback').textContent=text;sound(ok);updateHud();}
 function mistake(el){if(!st||st.busy||st.done)return;st.errors++;st.lives=Math.max(0,st.lives-1);el?.classList.add('wrong');feedback(false,'Ez da zuzena. Beste aukera bat probatu!');if(st.lives<=0){st.busy=true;const failedRound=st;setTimeout(()=>{if(st===failedRound)finish()},750);return}st.busy=true;const failedRound=st;setTimeout(()=>{if(st===failedRound&&!st.done){st.busy=false;el?.classList.remove('wrong');$('feedback').className='v8-feedback';$('feedback').textContent='Saiatu berriro!'}},650)}
 function success(el,text,onNext){if(!st||st.busy||st.done)return;st.busy=true;st.correct++;el?.classList.add('correct');feedback(true,text||'Bikain! Erantzun zuzena!');const answeredRound=st;setTimeout(()=>{if(st!==answeredRound||st.done)return;st.busy=false;onNext();},750)}
 function chooseLocation(id,el){if(!st||st.stage!==1||st.busy)return;const q=locations[st.mapIndex];if(id!==q.id){mistake(el);return}const loc=locations.find(x=>x.id===id);const reveal=$('map-reveal');if(reveal)reveal.innerHTML=`<div class="v8-map-label" style="left:${loc.x}%;top:${loc.y+7}%">✓ ${esc(loc.label)}</div>`;success(el,'Bikain! '+loc.label+' aurkitu duzu.',()=>{st.mapIndex++;if(st.mapIndex>=4)levelUp(2);else render()});}
 function chooseTribe(id,where,el){if(!st||st.stage!==2||st.phase!=='tribes'||st.busy)return;const fact=tribeFacts.find(x=>x.id===id);if(!fact||st.tribePlaced.includes(id))return;if(fact.answer!==where){mistake(el);return}st.selected=null;success(el,'Oso ondo! «'+fact.text+'» ondo kokatu duzu.',()=>{st.tribePlaced.push(id);if(st.tribePlaced.length===7){st.phase='common'}render()});}
 function chooseCommon(value,el){if(!st||st.stage!==2||st.phase!=='common'||st.busy)return;if(value!=='zuzena'){mistake(el);return}success(el,'Bikain! Arabiera eta Harri Beltzari gurtza.',()=>levelUp(3));}
 function chooseGoddess(id,el){if(!st||st.stage!==3||st.busy)return;const q=goddessQuestions[st.goddessIndex];if(id!==q.answer){mistake(el);return}success(el,'Bikain! '+goddessCards.find(x=>x[0]===id)[1]+' da.',()=>{st.goddessIndex++;if(st.goddessIndex>=3)finish();else render()});}
 function levelUp(n){if(!st||st.done)return;st.stage=n;st.unlocked=Math.max(st.unlocked,n);st.phase=n===2?'tribes':st.phase;render();const panel=$('transition');const title=n===2?'1. MAILA GAINDITUTA!':'2. MAILA GAINDITUTA!';const sub=n===2?'Orain bi tribu-moten bizimodua ezagutuko duzu.':'Orain Al-Uzza, Al-Lat eta Manat bereizi beharko dituzu.';panel.innerHTML=`<div class="v8-transition-card"><div style="font-size:55px">🏅</div><h2>${title}</h2><p>${sub}</p><button class="v8-primary" data-action="continue">HURRENGO MAILA ❯</button></div>`;panel.hidden=false;}
 function finish(){if(!st||st.done)return;st.done=true;if(timer)clearInterval(timer);timer=null;const won=st.correct===TOTAL&&st.time>0&&st.lives>0;const stored=won?saveScore():false;updateHud();$('play').hidden=true;$('complete').hidden=false;const high=leaderboard().find(x=>x.name.toLocaleLowerCase('eu')===st.nickname.toLocaleLowerCase('eu'))?.score??0;$('complete').innerHTML=`<div class="v8-end-card"><div style="font-size:60px">🏆</div><h2>${st.correct===TOTAL?'ABENTURA OSATUTA!':'PARTIDA AMAITU DA'}</h2><p>${esc(st.nickname)}, zure emaitza:</p><div class="v8-end-score">${scoreNow().toLocaleString('eu-ES')}</div><p><strong>${st.correct} / ${TOTAL}</strong> erantzun zuzen · ${st.errors} huts · Errekor pertsonala: ${stored?high.toLocaleString('eu-ES')+' puntu':'ezin izan da gorde'}</p><p>${won?(stored?'Amaitutako partida: TOP 10 lokala eguneratu da.':'Partida amaituta, baina nabigatzaileak ez du errekorra gordetzea baimendu.'):'Amaitu gabeko partida: emaitza partziala ez da errekorretan gordetzen.'} Sailkapena ez da Interneten partekatzen.</p><div class="v8-end-actions"><button class="v8-primary" data-action="retry">↻ BERRIRO JOLASTU</button><button class="v8-primary v8-secondary" data-action="home">⌂ MENURA ITZULI</button></div></div>`;}
 function onClick(e){const action=e.target.closest('[data-action]');if(action){switch(action.dataset.action){case'home':close();break;case'start':start();break;case'retry':{const name=st?.nickname||lastNick();intro();$('nickname').value=name;start();break}case'sound':muted=!muted;action.setAttribute('aria-pressed',String(muted));action.textContent=muted?'♩':'♪';break;case'continue':$('transition').hidden=true;break}return}
 const location=e.target.closest('[data-location]');if(location){chooseLocation(location.dataset.location,location);return}
 const token=e.target.closest('[data-token]');if(token){if(!st||st.stage!==2||st.phase!=='tribes'||st.busy)return;st.selected=token.dataset.token;renderTribes();$('feedback').textContent='Orain sakatu Barrualdekoak edo Kostaldekoak.';return}
 const tribe=e.target.closest('[data-tribe]');if(tribe){if(st?.selected)chooseTribe(st.selected,tribe.dataset.tribe,tribe);else $('feedback').textContent='Lehenik hautatu ezaugarrien txartel bat.';return}
 const c=e.target.closest('[data-common]');if(c){chooseCommon(c.dataset.common,c);return}
 const g=e.target.closest('[data-goddess]');if(g){chooseGoddess(g.dataset.goddess,g);return}}
 function onDragStart(e){const t=e.target.closest('[data-token]');if(!t||!st||st.stage!==2)return;st.selected=t.dataset.token;e.dataTransfer?.setData('text/plain',st.selected);e.dataTransfer.effectAllowed='move'}
 function onDragOver(e){const t=e.target.closest('[data-tribe]');if(t&&st&&st.stage===2&&st.phase==='tribes'){e.preventDefault();t.classList.add('drag-over');if(e.dataTransfer)e.dataTransfer.dropEffect='move'}}
 function clearDrag(){root()?.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))}
 function onDrop(e){const t=e.target.closest('[data-tribe]');if(!t||!st)return;e.preventDefault();const id=e.dataTransfer?.getData('text/plain')||st.selected;clearDrag();if(id)chooseTribe(id,t.dataset.tribe,t)}
 function onKeyDown(e){if(e.key==='Enter'&&e.target.id==='v8-nickname'){e.preventDefault();start()};if(e.key==='Escape'&&root())close()}
 // Preserve the already wired ten-game menu; only replace the first game's launcher.
 window.ARABIA_V7=Object.assign(window.ARABIA_V7||{}, {launch,close,testStart:(name='Proba01')=>{launch();$('nickname').value=name;start()},getState:()=>st&&({stage:st.stage,phase:st.phase,mapIndex:st.mapIndex,goddessIndex:st.goddessIndex,tribePlaced:[...st.tribePlaced],correct:st.correct,errors:st.errors,lives:st.lives,score:scoreNow(),done:st.done})});
 window.ARABIA_V8=window.ARABIA_V7;
})();

